async function apiRequest(path, options={}){
 const headers={'Content-Type':'application/json',...(options.headers||{})};
 if(API_TOKEN)headers.Authorization=`Bearer ${API_TOKEN}`;
 const response=await fetch(API_BASE+path,{method:options.method||'GET',headers,body:options.body?JSON.stringify(options.body):undefined});
 let data={}; try{data=await response.json()}catch{}
 if(!response.ok||data.ok===false)throw new Error(data.error||`Сервердин катасы: HTTP ${response.status}`);
 return data;
}
async function loadProductsFromApi(){
 const data=await apiRequest('/api/products');
 PRODUCTS=(Array.isArray(data.products)?data.products:[]).map(p=>({...p,cat:p.category||p.cat||'Без категории',price:Number(p.price||0),cost:Number(p.cost||0),stock:Array.isArray(p.stock)?p.stock:[0,0,0,0,0],icon:p.icon||'📦'}));
 PRODUCTS_FROM_API=true;
}
async function enterRole(id){
 const branchMode=id==='branch';
 const selectedBranch=branchMode?Number(document.getElementById('loginBranch')?.value||0):null;
 const login=document.getElementById(`login-${id}`)?.value.trim();
 const password=document.getElementById(`pass-${id}`)?.value;
 if(!login||!password){showToast('Логин менен паролду толтуруңуз.');return;}
 const btn=document.querySelector(`[data-role="${id}"]`); if(btn){btn.disabled=true;btn.textContent='Текшерилүүдө…';}
 try{
  const result=await apiRequest('/api/login',{method:'POST',body:{username:login,password}});
  const user=result.user;
  if(!user||!['director','admin','cashier','seller'].includes(user.role))throw new Error('Аккаунттун ролу туура эмес.');
  if(!branchMode&&user.role!==id)throw new Error('Бул логин башка ролго тиешелүү. Өзүңүздүн ролдун карточкасынан кириңиз.');
  if(branchMode&& !['director','admin'].includes(user.role))throw new Error('Филиал тандоо үчүн Руководитель же Администратор аккаунту керек.');
  if(branchMode&&user.role==='admin'&&Number(user.branchId)!==selectedBranch)throw new Error('Бул Администратор тандалган филиалга бекитилген эмес. Өз филиалыңызды тандаңыз.');
  API_TOKEN=result.token; AUTH_USER=user; sessionStorage.setItem('mmAuthToken',API_TOKEN); sessionStorage.setItem('mmAuthUser',JSON.stringify(user));
  currentRole=ROLES.find(r=>r.id===user.role)||ROLES.find(r=>r.id==='admin');
  currentBranch=user.role==='director'?(branchMode?selectedBranch:0):Number(user.branchId||0);
  try{await loadProductsFromApi();}catch(productErr){PRODUCTS=[];PRODUCTS_FROM_API=false;showToast('Кирүү ийгиликтүү, бирок товарлар жүктөлгөн жок: '+productErr.message);}
  document.getElementById('loginScreen').classList.add('hidden');document.getElementById('appScreen').classList.remove('hidden');
  document.getElementById('userName').textContent=user.username;document.getElementById('userRole').textContent=currentRole.name;document.getElementById('avatar').textContent=currentRole.icon;
  document.getElementById('topBranch').textContent=user.role==='director'&&!branchMode?'Бардык филиалдар':BRANCHES[currentBranch];
  const statusPill=document.querySelector('.top-actions .pill:last-child');if(statusPill){statusPill.innerHTML='<span class="online-dot"></span> D1 базага туташкан';}
  currentPage=user.role==='cashier'?'pos':'dashboard';startPresenceHeartbeat();buildNav();renderPage();
  if(PRODUCTS_FROM_API)showToast(`Система ачылды. Базадан ${PRODUCTS.length} товар жүктөлдү.`);
 }catch(err){showToast(err.message||'Кирүү ишке ашкан жок.');}
 finally{if(btn){btn.disabled=false;btn.textContent=branchMode?'Войти в филиал':'Войти';}}
}
