function pageTitle(){const map={dashboard:['Главная панель','Обзор сети магазинов'],analytics:['Аналитика','Ключевые показатели и динамика'],branches:['Филиалы','Сравнение работы торговых точек'],sales:['Продажи','Журнал демонстрационных операций'],products:['Каталог товаров','Поиск, цены, штрих-коды и категории'],stock:['Склад и остатки','Наличие товаров по филиалам'],staff:['Сотрудники','Роли и доступ к системе'],finance:['Финансы','Сводные финансовые показатели'],reports:['Отчёты','Формирование и отправка отчётов'],settings:['Настройки','Параметры демонстрационного интерфейса'],pos:['Касса (POS)','Продажа товаров по штрих-коду'],shift:['Смена кассира','Открытие и закрытие смены'],orders:['Заказы','Демонстрационные заказы'],workreport:['Жумуш отчёттору','Филиалдык текшерүү жана смена боюнча отчёт'],chat:['Командалык чат','Жалпы чат, жетекчилик тобу жана филиалдык топтор'],profile:['Профиль','Сүрөт, иконка жана ролго тиешелүү рамка']};return map[currentPage]||map.dashboard;}
function renderPage(){if(CHAT_POLL_TIMER){clearInterval(CHAT_POLL_TIMER);CHAT_POLL_TIMER=null;}if(!canAccessPage(currentPage)){currentPage=ROLE_NAV[AUTH_USER?.role]?.[0]?.[0]||'products';}const [title,sub]=pageTitle();document.getElementById('topTitle').textContent=title;document.getElementById('topSubtitle').textContent=sub;const content=document.getElementById('content');const dashboard=currentRole?.id==='director'?dashboardView:currentRole?.id==='admin'?adminDashboardView:sellerDashboardView;const views={dashboard,analytics:dashboardView,branches:branchesView,sales:salesView,products:productsView,stock:stockView,staff:staffView,finance:financeView,reports:reportsView,settings:settingsView,pos:posView,shift:shiftView,orders:ordersView,workreport:workReportView,chat:chatView,profile:profileView};content.innerHTML=(views[currentPage]||dashboard)();wirePage();if(currentPage==='chat'){loadChatData(true);CHAT_POLL_TIMER=setInterval(()=>loadChatData(false),8000);}if(currentPage==='profile')loadProfileData();if(currentPage==='workreport')loadWorkReports();}
