function sellerDashboardView(){const branch=Number(AUTH_USER?.branchId||0);const available=PRODUCTS.filter(p=>Number(p.stock?.[branch]||0)>0).length;const out=PRODUCTS.filter(p=>Number(p.stock?.[branch]||0)===0).length;return `<div class="page-head"><div><div class="eyebrow">ПРОДАВЕЦ-КОНСУЛЬТАНТ</div><h1>Кардарларга жардам берүү</h1><p>${escapeHtml(BRANCHES[branch])} · каталог жана товарлардын бар-жогу</p></div><div class="actions"><button class="btn" data-page="products">Каталогду ачуу</button><button class="btn dark" data-page="orders">Заказдар</button></div></div><section class="metric-grid"><div class="metric"><div class="metric-top">Каталогдогу товарлар</div><div class="metric-value">${PRODUCTS.length.toLocaleString('ru-RU')}</div><div class="metric-note">${PRODUCTS_FROM_API?'D1 базасынан':'База жүктөлгөн жок'}</div></div><div class="metric"><div class="metric-top">Филиалда бар товарлар</div><div class="metric-value">${available}</div><div class="metric-note">аталыш боюнча</div></div><div class="metric"><div class="metric-top">Калдыгы жок</div><div class="metric-value">${out}</div><div class="metric-note">Администраторго кабарлаңыз</div></div><div class="metric"><div class="metric-top">Сиздин ролуңуз</div><div class="metric-value" style="font-size:22px">Консультант</div><div class="metric-note">өзгөртүү/приход баасына укук жок</div></div></section><div class="panel"><div class="panel-head"><h3>Кардар үчүн тез издөө</h3><button class="btn dark" data-page="products">Издөөгө өтүү →</button></div><div class="panel-body"><p>Товарды аталышы же штрих-коду менен издеңиз. Сиз сатуу баасын жана өзүңүздүн филиалдагы бар-жогун көрөсүз. Закупочная баа, өзгөртүү жана импорт функциялары бул ролго берилбейт.</p><div class="notice">Заказдарды каттоо азырынча демо модулда; чыныгы заказ базасын кийинки этапта туташтырабыз.</div></div></div>`}
function dashboardView(){return `<div class="page-head"><div><div class="eyebrow">ПАНЕЛЬ УПРАВЛЕНИЯ</div><h1>Добрый день, руководитель 👋</h1><p>Сводная информация по работе «Мой Маркет»</p></div><div class="actions"><select class="select" id="dashBranch"><option value="all">Все филиалы</option>${BRANCHES.map((b,i)=>`<option value="${i}">${b}</option>`).join('')}</select><button class="btn" data-action="reports">↧ Отчёт за день</button></div></div><section class="metric-grid"><div class="metric" style="--glow:#155caa55"><div class="metric-top">Общая выручка <span class="metric-icon">₸</span></div><div class="metric-value" id="mRevenue">${fmt(dashboardBranch==='all'?5482300:[1540000,1205000,986000,874000,877300][Number(dashboardBranch)])}</div><div class="trend">↗ 12,4%</div><div class="metric-note">к прошлому периоду · демо</div></div><div class="metric" style="--glow:#00c78a33"><div class="metric-top">Расчётная валовая прибыль <span class="metric-icon">↗</span></div><div class="metric-value">1 246 700 сом</div><div class="trend">↗ 8,3%</div><div class="metric-note">по заданной себестоимости · демо</div></div><div class="metric" style="--glow:#a435ff35"><div class="metric-top">Количество продаж <span class="metric-icon">▤</span></div><div class="metric-value">3 582</div><div class="trend">↗ 5,1%</div><div class="metric-note">за выбранный период · демо</div></div><div class="metric" style="--glow:#ffb91433"><div class="metric-top">Средний чек <span class="metric-icon">◉</span></div><div class="metric-value">1 531 сом</div><div class="trend">↗ 3,6%</div><div class="metric-note">за выбранный период · демо</div></div></section><section class="panels"><div class="panel"><div class="panel-head"><h3>Динамика продаж</h3><div class="legend"><span>Выручка</span><span>Прибыль</span></div></div><div class="panel-body"><div class="chart">${[24,34,27,45,39,52,46,62,54,58,66,49,72,68,81,74,89,78,95,82,100,90,108,98].map((h,i)=>`<div class="bar-group"><div class="bar" style="height:${Math.min(h,100)}%"></div><div class="bar alt" style="height:${Math.max(8,h*.3)}%"></div>${i%4===0?`<span class="bar-label">${i/4+1} мар.</span>`:''}</div>`).join('')}</div></div></div><div class="panel"><div class="panel-head"><h3>Продажи по филиалам</h3><span class="badge good">Демо</span></div><div class="panel-body"><div class="branch-performance">${(dashboardBranch==='all'?[['№1 · Центр',1540000,100],['№2 · Восток',1205000,78],['№3 · Юг',986000,64],['№4 · Запад',874000,57],['№5 · Сити',877300,57]]:[[['№1 · Центр','№2 · Восток','№3 · Юг','№4 · Запад','№5 · Сити'][Number(dashboardBranch)],[1540000,1205000,986000,874000,877300][Number(dashboardBranch)],100]]).map(([n,v,w])=>`<div class="branch-row"><span>${n}</span><div class="branch-track"><div class="branch-fill" style="width:${w}%"></div></div><span class="branch-val">${(v/1000).toFixed(0)} тыс.</span></div>`).join('')}</div><p class="small muted" style="margin:17px 0 0">Суммы демонстрационные и не отражают реальные продажи.</p></div></div></section><section class="panels"><div class="panel"><div class="panel-head"><h3>Популярные товары</h3><button class="btn dark" data-page="products">Весь каталог →</button></div><div class="table-wrap"><table><thead><tr><th>Товар</th><th>Продано, шт.</th><th>Выручка</th></tr></thead><tbody>${[['Казан 5 л',428,642000,'🍲'],['Чайник электрический',356,463600,'🫖'],['Набор посуды',298,447000,'🍽️'],['Сковорода 28 см',412,453200,'🍳'],['Термос 1 л',310,279000,'♨️']].map(x=>`<tr><td><div class="product-cell"><div class="product-thumb">${x[3]}</div><strong>${x[0]}</strong></div></td><td>${x[1]}</td><td>${fmt(x[2])}</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panel-head"><h3>События и контроль</h3><span class="badge warn">Пример</span></div><div class="panel-body" style="display:grid;gap:12px"><div class="notice">⚠️ Микроволновая печь: остаток ниже порога в одном филиале.</div><div class="summary-line"><span>Ожидают приёмки</span><strong>3 документа</strong></div><div class="summary-line"><span>Не закрытые смены</span><strong>2</strong></div><div class="summary-line"><span>Последняя резервная копия</span><strong>Сегодня, 02:00*</strong></div><div class="small muted">* Демонстрационный статус, реальное резервное копирование не выполняется.</div></div></div></section>`}
function productsView(){const canManage=['director','admin'].includes(AUTH_USER?.role);return `<div class="page-head"><div><div class="eyebrow">ТОВАРНЫЙ СПРАВОЧНИК</div><h1>Каталог товаров</h1><p>${PRODUCTS_FROM_API?"Каталог загружен из постоянной базы D1":"Данные ещё не загружены из базы"} · пакетный импорт Excel/CSV</p></div><div class="actions">${canManage?`<button class="btn" data-action="newProduct">＋ Добавить товар</button><button class="btn dark" data-action="import">⇧ Импорт Excel/CSV</button>`:""}</div></div><div class="panel"><div class="toolbar"><input id="productSearch" class="search" placeholder="⌕ Поиск по названию, коду или штрих-коду…" value="${escapeHtml(searchTerm)}"><select id="catFilter" class="select"><option value="all">Все категории</option>${[...new Set(PRODUCTS.map(p=>p.cat))].map(c=>`<option>${escapeHtml(c)}</option>`).join('')}</select><select id="stockFilter" class="select"><option value="all">Все остатки</option><option value="low">Мало на складе</option><option value="out">Нет в наличии</option></select></div><div class="table-wrap"><table><thead><tr><th></th><th>Код</th><th>Штрих-код</th><th>Наименование</th><th>Категория</th><th>Цена продажи</th><th>Остаток в филиале</th><th>Статус</th>${canManage?'<th>Действия</th>':''}</tr></thead><tbody id="productsRows">${productRows()}</tbody></table></div><div class="panel-head"><span class="muted small" id="productCount">Найдено ${filteredProducts().length} товаров</span><span class="muted small">Изменения сохраняются в D1</span></div></div><div class="notice" style="margin-top:14px">${PRODUCTS_FROM_API?"Каталог загружен из D1. Название, категория и цены применяются ко всем филиалам; количество изменяется отдельно для выбранного филиала.":"Данные из базы не загружены. Войдите ещё раз или проверьте API."}</div>`}
function filteredProducts(){const s=searchTerm.toLowerCase();return PRODUCTS.filter(p=>{const qty=p.stock[currentBranch]??0;const matchesSearch=`${p.id} ${p.barcode} ${p.name} ${p.cat}`.toLowerCase().includes(s);const matchesCategory=categoryFilter==='all'||p.cat===categoryFilter;const matchesStock=stockFilter==='all'||(stockFilter==='low'&&qty>0&&qty<4)||(stockFilter==='out'&&qty===0);return matchesSearch&&matchesCategory&&matchesStock})}
function productRows(){const canManage=['director','admin'].includes(AUTH_USER?.role);return filteredProducts().map(p=>{const qty=p.stock[currentBranch]??0;return `<tr><td><div class="product-thumb">${escapeHtml(p.icon||'📦')}</div></td><td>${escapeHtml(p.id)}</td><td>${escapeHtml(p.barcode||'')}</td><td><strong>${escapeHtml(p.name)}</strong></td><td>${escapeHtml(p.cat)}</td><td>${fmt(p.price)}</td><td>${qty} шт.</td><td><span class="badge ${qty===0?'bad':qty<4?'warn':'good'}">${qty===0?'Нет в наличии':qty<4?'Мало':'Активен'}</span></td>${canManage?`<td><button type="button" class="btn dark" style="padding:8px 10px;white-space:nowrap" data-edit-product="${Number(p.dbId)||0}">✎ Изменить</button></td>`:''}</tr>`}).join('')||`<tr><td colspan="${canManage?9:8}"><div class="empty-state">Товары не найдены</div></td></tr>`}
function stockView(){const canManage=["director","admin"].includes(AUTH_USER?.role);return `<div class="page-head"><div><div class="eyebrow">УПРАВЛЕНИЕ ОСТАТКАМИ</div><h1>Склад и остатки</h1><p>${AUTH_USER?.role==="director"?"Остатки по пяти филиалам":"Остатки вашего филиала"}</p></div><div class="actions">${canManage?`<button class="btn dark" data-action="inventory">▤ Инвентаризация</button><button class="btn" data-action="transfer">⇄ Перемещение</button>`:""}</div></div><div class="panel"><div class="panel-head"><h3>${AUTH_USER?.role==='director'?'Остатки по филиалам':'Остатки вашего филиала'}</h3><select id="stockProduct" class="select">${PRODUCTS.map(p=>`<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Филиал</th><th>Остаток</th><th>Резерв</th><th>Доступно</th><th>Статус</th></tr></thead><tbody id="stockRows"></tbody></table></div></div><div class="panel" style="margin-top:15px"><div class="panel-head"><h3>Последние движения товара</h3><span class="badge warn">Пример</span></div><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Операция</th><th>Количество</th><th>Филиал</th><th>Ответственный</th></tr></thead><tbody><tr><td>16.10.2026 09:15</td><td><span class="badge good">Приход</span></td><td>+50</td><td>Центр</td><td>Администратор</td></tr><tr><td>16.10.2026 10:28</td><td>Продажа</td><td>-2</td><td>Восток</td><td>Кассир</td></tr><tr><td>16.10.2026 11:40</td><td>Перемещение</td><td>-5 / +5</td><td>Центр → Юг</td><td>Администратор</td></tr></tbody></table></div></div>`}
function wireStock(){const sel=document.getElementById('stockProduct');if(!sel)return;const rows=document.getElementById('stockRows');if(!PRODUCTS.length){if(rows)rows.innerHTML='<tr><td colspan="5"><div class="empty-state">Базада азырынча товар жок</div></td></tr>';return;}const branchIndexes=AUTH_USER?.role==='director'?[0,1,2,3,4]:[Number(AUTH_USER?.branchId||0)];const draw=()=>{const p=PRODUCTS.find(x=>x.id===sel.value)||PRODUCTS[0];if(!p||!rows)return;rows.innerHTML=branchIndexes.map(i=>{const q=Number(p.stock?.[i]||0);return `<tr><td>${escapeHtml(BRANCHES[i])}</td><td>${q} шт.</td><td>0</td><td><strong>${q}</strong></td><td><span class="badge ${q===0?'bad':q<4?'warn':'good'}">${q===0?'Нет':q<4?'Мало':'В наличии'}</span></td></tr>`}).join('')};sel.addEventListener('change',draw);draw()}
function posView(){return `<div class="page-head"><div><div class="eyebrow">ТОРГОВАЯ ОПЕРАЦИЯ</div><h1>Касса (POS)</h1><p>Демо-касса: сканирование и добавление тестовых товаров</p></div><div class="actions"><span class="pill">🏬 ${BRANCHES[currentBranch]}</span><span class="pill"><span class="online-dot"></span> Смена: демо</span></div></div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Добавить товар</h3><span class="badge good">Сканер / поиск</span></div><div class="panel-body"><input id="posSearch" class="search" style="width:100%;margin-bottom:12px" placeholder="Штрих-код или название товара…"><div id="posProducts" style="display:grid;gap:8px">${posProductChoices()}</div></div></div><div class="panel"><div class="panel-head"><h3>Текущий чек</h3><button class="btn dark" data-action="clearCart">Очистить</button></div><div class="panel-body"><div id="cartItems">${cartHTML()}</div><div class="cart-total"><span>Итого</span><span id="cartTotal">${fmt(cart.reduce((a,x)=>a+x.price*x.qty,0))}</span></div><div class="actions" style="display:grid;grid-template-columns:repeat(3,1fr)"><button class="btn green" data-pay="Наличные">Наличные</button><button class="btn" data-pay="Карта">Карта</button><button class="btn purple" data-pay="QR">QR</button></div><p class="muted small">Кнопка оплаты имитирует чек в браузере; реальные платежи не выполняются.</p></div></div></div>`}
function posProductChoices(){return PRODUCTS.slice(0,8).map(p=>`<button class="pill" style="width:100%;justify-content:flex-start;padding:10px" data-add="${escapeHtml(p.id)}"><span style="font-size:22px">${escapeHtml(p.icon||'📦')}</span><span style="flex:1;text-align:left"><strong style="display:block;color:#fff">${escapeHtml(p.name)}</strong><span class="muted small">${escapeHtml(p.barcode||'')}</span></span><strong>${fmt(p.price)}</strong><span style="color:#5ed4ff;font-size:18px">＋</span></button>`).join('')}
function cartHTML(){if(!cart.length)return '<div class="empty-state">🛒<br>Чек пуст<br><span class="small">Добавьте товар из списка</span></div>';return cart.map(x=>`<div class="summary-line"><span style="flex:1">${escapeHtml(x.icon||'📦')} ${escapeHtml(x.name)}<div class="muted small">${fmt(x.price)} × ${x.qty}</div></span><span><button class="btn dark" style="padding:4px 8px" data-minus="${escapeHtml(x.id)}">−</button> <button class="btn dark" style="padding:4px 8px" data-plus="${escapeHtml(x.id)}">＋</button></span><strong>${fmt(x.price*x.qty)}</strong></div>`).join('')}
function salesView(){return `<div class="page-head"><div><div class="eyebrow">ЖУРНАЛ ОПЕРАЦИЙ</div><h1>Продажи</h1><p>Сейчас отображаются только локальные демо-чеки этой сессии; постоянный API продаж ещё не подключён.</p></div><button class="btn dark" data-action="export">⇩ Экспорт отчёта</button></div><div class="panel"><div class="toolbar"><input class="search" id="salesSearch" placeholder="Поиск по номеру чека или сотруднику…"><select class="select"><option>Сегодня</option><option>7 дней</option><option>Этот месяц</option></select></div><div class="table-wrap"><table><thead><tr><th>Чек</th><th>Дата и время</th><th>Филиал</th><th>Кассир</th><th>Оплата</th><th>Сумма</th><th>Статус</th></tr></thead><tbody id="salesRows">${salesRows()}</tbody></table></div></div>`}
function salesRows(){const rows=JSON.parse(sessionStorage.getItem('demoSales')||'[]');return rows.length?rows.map(r=>`<tr>${r.map((v,i)=>i===6?`<td><span class="badge good">${escapeHtml(v)}</span></td>`:`<td>${typeof v==='number'?fmt(v):escapeHtml(v)}</td>`).join('')}</tr>`).join(''):'<tr><td colspan="7"><div class="empty-state">Азырынча чек жок. Бул беттеги төлөмдөр демо режимде жана базага сакталбайт.</div></td></tr>'}
function branchesView(){return `<div class="page-head"><div><div class="eyebrow">СЕТЬ МАГАЗИНОВ</div><h1>Филиалы</h1><p>Единый каталог, отдельные остатки и кассовые смены</p></div></div><section class="metric-grid">${BRANCHES.map((b,i)=>`<div class="metric"><div class="metric-top">${b}<span class="metric-icon">🏬</span></div><div class="metric-value">${[1540000,1205000,986000,874000,877300][i].toLocaleString('ru-RU')}</div><div class="metric-note">сом · демонстрационная выручка</div><div style="margin-top:13px"><span class="badge good">Демо-активен</span></div><button class="btn dark" style="width:100%;margin-top:13px" data-branch="${i}">Открыть филиал</button></div>`).join('')}</section><div class="notice">Каждый филиал должен иметь отдельные права доступа, кассу и складские остатки; здесь это показано в интерфейсе без серверной авторизации.</div>`}
function staffView(){const canAdd=['director','admin'].includes(AUTH_USER?.role);return `<div class="page-head"><div><div class="eyebrow">КОМАНДА И ДОСТУП</div><h1>Сотрудники</h1><p>${AUTH_USER?.role==='director'?'Все филиалы · создание сотрудников с назначением филиала':'Сотрудники только вашего филиала'}</p></div>${canAdd?'<button class="btn" data-action="newStaff">＋ Добавить сотрудника</button>':''}</div><div class="panel"><div class="panel-head"><h3>Аккаунты системы</h3><button class="btn dark" type="button" data-refresh-staff>↻ Обновить</button></div><div class="table-wrap"><table><thead><tr><th>Логин</th><th>Роль</th><th>Филиал</th><th>Создан</th><th>Статус</th><th>Доступ</th></tr></thead><tbody id="staffRows"><tr><td colspan="6">Загрузка сотрудников…</td></tr></tbody></table></div></div><div class="notice" style="margin-top:14px">Руководитель может добавлять Администраторов, Кассиров и Продавцов для любого филиала. Администратор может добавлять только Кассиров и Продавцов в свой филиал. Пароли никогда не отображаются.</div>`}
function financeView(){return `<div class="page-head"><div><div class="eyebrow">ФИНАНСОВЫЙ КОНТРОЛЬ</div><h1>Финансы</h1><p>Кассовая дисциплина и расчётная прибыль</p></div></div><section class="metric-grid"><div class="metric"><div class="metric-top">Наличные · демо</div><div class="metric-value">2 140 500 сом</div><div class="metric-note">поступления по примеру</div></div><div class="metric"><div class="metric-top">Карта / QR · демо</div><div class="metric-value">3 341 800 сом</div><div class="metric-note">без привязки к банку</div></div><div class="metric"><div class="metric-top">Возвраты · демо</div><div class="metric-value">28 400 сом</div><div class="metric-note">пример для интерфейса</div></div><div class="metric"><div class="metric-top">Кассовая разница</div><div class="metric-value">0 сом</div><div class="metric-note">не реальные данные</div></div></section><div class="panel"><div class="panel-head"><h3>Правила расчёта</h3></div><div class="panel-body"><p>Выручка считается по завершённым продажам за вычетом возвратов. Валовая прибыль рассчитывается по себестоимости товаров. Для чистой прибыли дополнительно нужны аренда, зарплата, доставка, налоги и прочие расходы.</p></div></div>`}
function reportsView(){return `<div class="page-head"><div><div class="eyebrow">ОТЧЁТНОСТЬ</div><h1>Автоматические отчёты</h1><p>Настройка будущей отправки руководителю</p></div></div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Формирование отчёта</h3></div><div class="panel-body"><div class="form-grid"><div class="form-row"><label>Тип отчёта</label><select id="reportType"><option>Сводка по всем филиалам</option><option>Продажи по филиалу</option><option>Остатки товаров</option><option>Кассовые смены</option><option>Продажи по сотрудникам</option></select></div><div class="form-row"><label>Период</label><select id="reportPeriod"><option>Сегодня</option><option>Вчера</option><option>Последние 7 дней</option><option>Текущий месяц</option></select></div><div class="form-row"><label>Филиал</label><select id="reportBranch"><option>Все филиалы</option>${BRANCHES.map(b=>`<option>${b}</option>`).join('')}</select></div><div class="form-row"><label>Формат</label><select id="reportFormat"><option>PDF (макет)</option><option>Excel / CSV (макет)</option></select></div></div><button class="btn" style="margin-top:16px" data-action="generateReport">Создать пример отчёта</button></div></div><div class="panel"><div class="panel-head"><h3>Каналы доставки</h3></div><div class="panel-body" style="display:grid;gap:12px"><div class="summary-line"><span>✉️ Email</span><span class="badge warn">Не подключён</span></div><div class="summary-line"><span>➤ Telegram</span><span class="badge warn">Не подключён</span></div><div class="summary-line"><span>📄 PDF / Excel</span><span class="badge good">Макет интерфейса</span></div><div class="notice">Чтобы включить автоматическую отправку, необходимо настроить серверный планировщик, адреса получателей и секретные токены.</div></div></div></div><div id="reportResult"></div>`}
function settingsView(){return `<div class="page-head"><div><div class="eyebrow">СИСТЕМНЫЕ ПАРАМЕТРЫ</div><h1>Настройки</h1><p>Демонстрационные параметры интерфейса</p></div></div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Информация о системе</h3></div><div class="panel-body"><div class="summary-line"><span>Название</span><strong>Мой Маркет PRO</strong></div><div class="summary-line"><span>Количество филиалов</span><strong>5</strong></div><div class="summary-line"><span>План каталога</span><strong>10 000+ товаров</strong></div><div class="summary-line"><span>Статус</span><span class="badge warn">UI-прототип</span></div></div></div><div class="panel"><div class="panel-head"><h3>Безопасное внедрение</h3></div><div class="panel-body"><p>Перед реальным запуском необходимо подключить базу данных, серверную авторизацию, резервное копирование, аудит операций и права доступа для каждой роли.</p><button class="btn dark" data-action="exportDemo">Скачать демонстрационные данные (CSV)</button></div></div></div>`}
function shiftView(){return `<div class="page-head"><div><div class="eyebrow">КАССОВАЯ ДИСЦИПЛИНА</div><h1>Смена кассира</h1><p>Пример открытия и закрытия смены</p></div></div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Текущая смена</h3><span class="badge warn">Демо</span></div><div class="panel-body"><div class="summary-line"><span>Кассир</span><strong>Демо-кассир</strong></div><div class="summary-line"><span>Филиал</span><strong>${BRANCHES[currentBranch]}</strong></div><div class="summary-line"><span>Начальный остаток</span><strong>5 000 сом</strong></div><div class="summary-line"><span>Продажи наличными</span><strong>12 400 сом</strong></div><div class="summary-line"><span>Продажи картой / QR</span><strong>18 600 сом</strong></div><button class="btn" style="width:100%;margin-top:15px" data-action="closeShift">Закрыть демо-смену</button></div></div><div class="panel"><div class="panel-head"><h3>Правильное закрытие</h3></div><div class="panel-body"><p>Кассир вводит фактически пересчитанную наличность. Система сравнивает её с расчётной суммой, сохраняет результат сверки и отправляет уведомление руководителю при расхождении.</p><div class="notice">Прототип не подключён к денежным операциям и не может подтвердить реальный остаток кассы.</div></div></div></div>`}
function ordersView(){return `<div class="page-head"><div><div class="eyebrow">ЗАКАЗЫ</div><h1>Заказы</h1><p>Демонстрационный список заказов клиентов</p></div><button class="btn" data-action="newOrder">＋ Создать заказ</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Номер</th><th>Дата</th><th>Клиент</th><th>Филиал</th><th>Сумма</th><th>Статус</th></tr></thead><tbody><tr><td>ORD-1048</td><td>16.10.2026 12:02</td><td>Клиент демо</td><td>Центр</td><td>3 650 сом</td><td><span class="badge warn">Новый</span></td></tr><tr><td>ORD-1047</td><td>16.10.2026 11:44</td><td>Клиент демо</td><td>Сити</td><td>2 800 сом</td><td><span class="badge good">Готов</span></td></tr></tbody></table></div></div>`}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function wirePage(){document.querySelectorAll('[data-page]').forEach(b=>{if(!b.closest('#nav'))b.addEventListener('click',()=>navigateToPage(b.dataset.page))});document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>handleAction(b.dataset.action)));const productRowsTarget=document.getElementById('productsRows');if(productRowsTarget)productRowsTarget.addEventListener('click',e=>{const btn=e.target.closest('[data-edit-product]');if(!btn)return;const product=PRODUCTS.find(p=>Number(p.dbId)===Number(btn.dataset.editProduct));if(product)openEditProductModal(product);});document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>addToCart(b.dataset.add)));document.querySelectorAll('[data-minus]').forEach(b=>b.addEventListener('click',()=>changeQty(b.dataset.minus,-1)));document.querySelectorAll('[data-plus]').forEach(b=>b.addEventListener('click',()=>changeQty(b.dataset.plus,1)));document.querySelectorAll('[data-pay]').forEach(b=>b.addEventListener('click',()=>payDemo(b.dataset.pay)));document.querySelectorAll('[data-branch]').forEach(b=>b.addEventListener('click',()=>{if(AUTH_USER?.role!=='director'){showToast('Филиалды башкара Руководитель гана укуктуу.');return;}currentBranch=Number(b.dataset.branch);document.getElementById('topBranch').textContent=BRANCHES[currentBranch];navigateToPage('dashboard');showToast('Выбран '+BRANCHES[currentBranch]+'.')}));const updateProductList=()=>{const rows=document.getElementById('productsRows');if(!rows)return;rows.innerHTML=productRows();const label=document.getElementById('productCount');if(label)label.textContent=`Найдено ${filteredProducts().length} товаров`;};const ps=document.getElementById('productSearch');if(ps)ps.addEventListener('input',e=>{searchTerm=e.target.value;updateProductList()});const catSelect=document.getElementById('catFilter');if(catSelect){catSelect.value=categoryFilter;catSelect.addEventListener('change',e=>{categoryFilter=e.target.value;updateProductList()})}const stockSelect=document.getElementById('stockFilter');if(stockSelect){stockSelect.value=stockFilter;stockSelect.addEventListener('change',e=>{stockFilter=e.target.value;updateProductList()})}const psearch=document.getElementById('posSearch');if(psearch)psearch.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.getElementById('posProducts').innerHTML=PRODUCTS.filter(p=>(p.name+' '+p.barcode+' '+p.id).toLowerCase().includes(q)).map(p=>`<button class="pill" style="width:100%;justify-content:flex-start;padding:10px" data-add="${escapeHtml(p.id)}"><span style="font-size:22px">${escapeHtml(p.icon||'📦')}</span><span style="flex:1;text-align:left"><strong style="display:block;color:#fff">${escapeHtml(p.name)}</strong><span class="muted small">${escapeHtml(p.barcode||'')}</span></span><strong>${fmt(p.price)}</strong><span style="color:#5ed4ff;font-size:18px">＋</span></button>`).join('')||'<div class="empty-state">Товар не найден</div>';document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>addToCart(b.dataset.add)));});const staffRefresh=document.querySelector('[data-refresh-staff]');if(staffRefresh)staffRefresh.addEventListener('click',loadStaffList);const staffRowsTarget=document.getElementById('staffRows');if(staffRowsTarget)staffRowsTarget.addEventListener('click',async e=>{const btn=e.target.closest('[data-staff-toggle]');if(!btn)return;const userId=Number(btn.dataset.staffToggle);const nextActive=btn.dataset.active!=='1';if(!Number.isInteger(userId)||userId<1)return;if(!confirm(nextActive?'Бул кызматкердин аккаунтун активдештиресизби?':'Бул кызматкердин кирүүсүн өчүрөсүзбү?'))return;btn.disabled=true;try{await apiRequest('/api/staff/status',{method:'POST',body:{userId,active:nextActive}});showToast('Кызматкердин статусу сакталды.');await loadStaffList();}catch(err){showToast(err.message||'Статус өзгөргөн жок.');btn.disabled=false;}});if(currentPage==='staff')loadStaffList();wireStock();const salesSearch=document.getElementById('salesSearch');if(salesSearch)salesSearch.addEventListener('input',e=>{const target=document.getElementById('salesRows');if(!target)return;const q=e.target.value.toLowerCase();target.innerHTML=salesRows().split('</tr>').filter(row=>row.toLowerCase().includes(q)).join('</tr>')});const dashBranch=document.getElementById('dashBranch');if(dashBranch){dashBranch.value=dashboardBranch;dashBranch.addEventListener('change',e=>{dashboardBranch=e.target.value;renderPage()})}
 if(currentPage==='chat')wireChatPage();
 if(currentPage==='profile')wireProfilePage();
 if(currentPage==='workreport')wireWorkReportPage();
}
function addToCart(id){const p=PRODUCTS.find(x=>x.id===id);if(!p)return;const existing=cart.find(x=>x.id===id);if(existing)existing.qty++;else cart.push({...p,qty:1});refreshCart();showToast('Добавлено в чек: '+p.name)}function changeQty(id,d){const item=cart.find(x=>x.id===id);if(!item)return;item.qty+=d;if(item.qty<=0)cart=cart.filter(x=>x.id!==id);refreshCart()}function refreshCart(){const target=document.getElementById('cartItems');if(target)target.innerHTML=cartHTML();const total=document.getElementById('cartTotal');if(total)total.textContent=fmt(cart.reduce((a,x)=>a+x.price*x.qty,0));document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>changeQty(b.dataset.minus,-1));document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>changeQty(b.dataset.plus,1));}
function payDemo(method){if(!cart.length){showToast('Сначала добавьте товары в чек.');return}const total=cart.reduce((a,x)=>a+x.price*x.qty,0);const rows=JSON.parse(sessionStorage.getItem('demoSales')||'[]');rows.unshift(['MM-'+(1043+rows.length),new Date().toLocaleString('ru-RU'),BRANCHES[currentBranch].replace('Филиал №','').replace(' — ',' · '),'Демо-кассир',method,total,'Завершён']);sessionStorage.setItem('demoSales',JSON.stringify(rows));cart=[];showToast('Демо-чек завершён. Оплата '+method+' не проводилась. Сумма: '+fmt(total));renderPage()}
const ROLE_LABELS={director:'Руководитель',admin:'Администратор',cashier:'Кассир',seller:'Продавец-консультант'};
function renderStaffRows(){const tbody=document.getElementById('staffRows');if(!tbody)return;if(!STAFF_DATA.length){tbody.innerHTML='<tr><td colspan="6"><div class="empty-state">Сотрудники не найдены.</div></td></tr>';return;}tbody.innerHTML=STAFF_DATA.map(u=>{const branch=Number(u.branchId);const isSelf=u.username===AUTH_USER?.username;const canManage=AUTH_USER?.role==='director'?u.role!=='director'&&u.id!==AUTH_USER.id:['admin'].includes(AUTH_USER?.role)&&['cashier','seller'].includes(u.role)&&branch===Number(AUTH_USER.branchId)&&!isSelf;return `<tr><td><strong>${escapeHtml(u.username)}</strong></td><td>${escapeHtml(ROLE_LABELS[u.role]||u.role)}</td><td>${u.role==='director'?'Все филиалы':escapeHtml(BRANCHES[branch]||'—')}</td><td>${escapeHtml(u.createdAt||'—')}</td><td><span class="badge ${u.active?'good':'bad'}">${u.active?'Активен':'Отключён'}</span></td><td>${canManage?`<button type="button" class="btn ${u.active?'dark':'green'}" style="padding:7px 9px" data-staff-toggle="${u.id}" data-active="${u.active?'1':'0'}">${u.active?'Отключить':'Включить'}</button>`:'—'}</td></tr>`;}).join('');}
async function loadStaffList(){const tbody=document.getElementById('staffRows');if(!tbody)return;tbody.innerHTML='<tr><td colspan="6">Жүктөлүүдө…</td></tr>';try{const data=await apiRequest('/api/staff');STAFF_DATA=Array.isArray(data.staff)?data.staff:[];renderStaffRows();}catch(err){tbody.innerHTML=`<tr><td colspan="6"><div class="empty-state">${escapeHtml(err.message||'Сотрудники жүктөлгөн жок.')}</div></td></tr>`;}}
function openStaffModal(){if(!AUTH_USER||!['director','admin'].includes(AUTH_USER.role)){showToast('Кызматкер кошууга уруксат жок.');return;}const old=document.getElementById('staffModal');if(old)old.remove();const director=AUTH_USER.role==='director';const roles=director?[['admin','Администратор'],['cashier','Кассир'],['seller','Продавец-консультант']]:[['cashier','Кассир'],['seller','Продавец-консультант']];const branchSelect=BRANCHES.map((b,i)=>`<option value="${i}" ${i===Number(AUTH_USER.branchId)?'selected':''} ${!director&&i!==Number(AUTH_USER.branchId)?'disabled':''}>${escapeHtml(b)}</option>`).join('');const modal=document.createElement('div');modal.id='staffModal';modal.style.cssText='position:fixed;inset:0;z-index:10002;background:#020813d9;display:grid;place-items:center;padding:16px;overflow:auto;';modal.innerHTML=`<section role="dialog" aria-modal="true" style="width:min(560px,100%);max-height:92vh;overflow:auto;background:#102238;border:1px solid #314b65;border-radius:18px;padding:22px;color:#edf6ff;box-shadow:0 22px 70px #0009"><div style="display:flex;align-items:center;justify-content:space-between;gap:12px"><h2 style="margin:0;font-size:22px">Добавить сотрудника</h2><button type="button" class="btn dark" id="closeStaffTop">✕</button></div><form id="staffForm" style="display:grid;gap:12px;margin-top:18px"><label>Логин<input class="field" id="staffUsername" required minlength="3" maxlength="40" pattern="[A-Za-z0-9_.-]+" autocomplete="off" placeholder="cashier_mm02"></label><label>Роль<select class="select" id="staffRole">${roles.map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></label><label>Филиал<select class="select" id="staffBranch" ${director?'':'disabled'}>${branchSelect}</select></label><label>Пароль<input class="field" id="staffPassword" type="password" required minlength="10" maxlength="200" autocomplete="new-password" placeholder="Кеминде 10 белги"></label><div id="staffFormError" role="status" style="color:#ffb5b5;white-space:pre-wrap"></div><div style="display:flex;justify-content:flex-end;gap:10px"><button type="button" class="btn dark" id="cancelStaff">Отмена</button><button type="submit" class="btn" id="saveStaff">Создать аккаунт</button></div><p class="small muted" style="margin:0">Пароль хранится только в виде хэша и не отображается в списке сотрудников.</p></form></section>`;document.body.appendChild(modal);const close=()=>modal.remove();modal.querySelector('#closeStaffTop').addEventListener('click',close);modal.querySelector('#cancelStaff').addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close();});modal.querySelector('#staffForm').addEventListener('submit',async e=>{e.preventDefault();const save=modal.querySelector('#saveStaff');const error=modal.querySelector('#staffFormError');save.disabled=true;save.textContent='Создание…';error.textContent='';const payload={username:modal.querySelector('#staffUsername').value.trim(),role:modal.querySelector('#staffRole').value,branchId:Number(modal.querySelector('#staffBranch').value),password:modal.querySelector('#staffPassword').value};try{await apiRequest('/api/staff',{method:'POST',body:payload});close();await loadStaffList();showToast('✅ Аккаунт кызматкерлер тизмесине кошулду.');}catch(err){error.textContent=err.message||'Аккаунт түзүлгөн жок.';save.disabled=false;save.textContent='Создать аккаунт';}});}
function handleAction(a){switch(a){case'reports':navigateToPage('reports');break;case'clearCart':cart=[];refreshCart();break;case'import':openImportModal();break;case'newProduct':openProductModal();break;case'transfer':showToast('Перемещение будет подтверждаться двумя действиями: отправка и приёмка.');break;case'inventory':showToast('Инвентаризация потребует сканирования и подтверждения фактического остатка.');break;case'export':case'generateReport':{const type=document.getElementById('reportType')?.value||'Сводка по продажам';const period=document.getElementById('reportPeriod')?.value||'Сегодня';const branch=document.getElementById('reportBranch')?.value||'Все филиалы';const target=document.getElementById('reportResult');if(target)target.innerHTML=`<div class="panel" style="margin-top:14px"><div class="panel-head"><h3>Пример отчёта готов</h3><span class="badge warn">Демо</span></div><div class="panel-body"><strong>${type}</strong><p class="muted">Период: ${period} · ${branch}</p><p>Отчёт содержит демонстрационные сведения. Отправка в Telegram и выгрузка PDF/Excel пока не подключены.</p><button class="btn dark" data-action="exportDemo">Скачать демонстрационные данные (CSV)</button></div></div>`;showToast('Сформирован макет отчёта. Реальные данные ещё не подключены.');wirePage();break}case'exportDemo':downloadCSV();break;case'closeShift':showToast('Демо-смена отмечена как закрытая. Реальная касса не затронута.');break;case'newStaff':openStaffModal();break;case'refreshStaff':loadStaffList();break;case'newOrder':showToast('Форма заказа появится после подключения каталога и базы данных.');break;}}
const IMPORT_BATCH_SIZE=20;
const IMPORT_MAX_ROWS=50000;
let SHEETJS_PROMISE=null;
function normalizeImportHeader(value){return String(value??'').replace(/^\uFEFF/,'').trim().toLowerCase().replace(/ё/g,'е').replace(/[^a-zа-я0-9]+/gi,'');}
function parseCsvMatrix(text){
 const first=(String(text).replace(/^\uFEFF/,'').split(/\r?\n/,1)[0]||'');
 let delimiter=';';let best=-1;
 for(const d of ['; ',',','\t'].map(x=>x.trim()).filter(Boolean)){
  let count=0,quoted=false;
  for(let i=0;i<first.length;i++){const ch=first[i];if(ch==='"'){if(quoted&&first[i+1]==='"'){i++;continue;}quoted=!quoted;}else if(ch===d&&!quoted)count++;}
  if(count>best){best=count;delimiter=d;}
 }
 const rows=[];let row=[],cell='',quoted=false;const source=String(text).replace(/^\uFEFF/,'');
 for(let i=0;i<source.length;i++){
  const ch=source[i];
  if(ch==='"'){
   if(quoted&&source[i+1]==='"'){cell+='"';i++;}
   else quoted=!quoted;
  }else if(ch===delimiter&&!quoted){row.push(cell);cell='';}
  else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&source[i+1]==='\n')i++;row.push(cell);if(row.some(v=>String(v).trim()!==''))rows.push(row);row=[];cell='';}
  else cell+=ch;
 }
 row.push(cell);if(row.some(v=>String(v).trim()!==''))rows.push(row);
 return rows;
}
function loadSheetJs(){
 if(window.XLSX)return Promise.resolve(window.XLSX);
 if(SHEETJS_PROMISE)return SHEETJS_PROMISE;
 SHEETJS_PROMISE=new Promise((resolve,reject)=>{
  const script=document.createElement('script');script.dataset.sheetjsImport='1';script.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';
  script.onload=()=>window.XLSX?resolve(window.XLSX):reject(new Error('Не удалось загрузить библиотеку для чтения Excel.'));
  script.onerror=()=>{script.remove();reject(new Error('Не удалось загрузить библиотеку Excel. Проверьте интернет или используйте CSV.'));};
  document.head.appendChild(script);
 }).catch(err=>{SHEETJS_PROMISE=null;throw err;});
 return SHEETJS_PROMISE;
}
function importHeaderMap(header){
 const aliases={
  category:['категория','названиекатегории','category','cat'],
  name:['названиетовара','наименование','товар','name','product','productname'],
  barcode:['штрихкод','barcode','ean','barcode','кодштрихкода'],
  cost:['ценаприход','приход','себестоимость','закупочнаяцена','cost','costprice','purchaseprice'],
  price:['ценавпродаже','ценапродажи','розничнаяцена','цена','price','saleprice','retailprice'],
  quantity:['количество','остаток','остатоквфилиале','quantity','qty','stock'],
  branch:['филиал','филиалномер','branch','filial','branchoffice']
 };
 const normalized=header.map(normalizeImportHeader),map={};
 for(const [field,names] of Object.entries(aliases)){map[field]=normalized.findIndex(h=>names.includes(h));}
 return map;
}
function parseImportNumber(value){if(typeof value==='number')return Number.isFinite(value)?value:NaN;const raw=String(value??'').trim().replace(/[\s\u00a0]/g,'').replace(',','.');if(!raw)return NaN;return Number(raw);}
function importBranchId(value,fallback){
 const raw=String(value??'').trim();if(!raw)return fallback;
 const n=normalizeImportHeader(raw);
 const byName=BRANCHES.findIndex(b=>normalizeImportHeader(b)===n);if(byName>=0)return byName;
 if(['центр','central','center'].includes(n))return 0;if(['восток','east'].includes(n))return 1;if(['юг','south'].includes(n))return 2;if(['запад','west'].includes(n))return 3;if(['сити','city'].includes(n))return 4;
 const match=n.match(/(?:филиал)?(?:номер)?([1-5])/);if(match)return Number(match[1])-1;
 if(/^[0-4]$/.test(n))return Number(n);
 return -1;
}
async function fileToImportMatrix(file){
 const ext=(file.name.split('.').pop()||'').toLowerCase();
 if(ext==='csv'||file.type==='text/csv')return parseCsvMatrix(await file.text());
 if(!['xlsx','xls','xlsm'].includes(ext))throw new Error('Выберите файл в формате .csv, .xlsx или .xls.');
 const XLSX=await loadSheetJs();const buffer=await file.arrayBuffer();const book=XLSX.read(buffer,{type:'array',cellDates:false});const sheetName=book.SheetNames[0];if(!sheetName)throw new Error('В Excel-файле не найден лист.');return XLSX.utils.sheet_to_json(book.Sheets[sheetName],{header:1,raw:false,defval:'',blankrows:false});
}
function parseImportRows(matrix,defaultBranchId){
 if(!matrix.length)throw new Error('Файл пуст.');
 const headers=importHeaderMap(matrix[0]);
 const required=[['category','Название категории/Категория'],['name','Название товара/Наименование'],['cost','Цена приход/Себестоимость'],['price','Цена в продаже/Цена'],['quantity','Количество/Остаток']];
 const missing=required.filter(([key])=>headers[key]<0).map(([,label])=>label);
 if(missing.length)throw new Error('Не найдены обязательные столбцы: '+missing.join(', ')+'. Используйте CSV-шаблон.');
 const parsed=[],fileDuplicates=new Set(),barcodeNames=new Map();
 for(let i=1;i<matrix.length;i++){
  const row=matrix[i]||[];if(!row.some(v=>String(v??'').trim()!==''))continue;
  const value=key=>headers[key]>=0?row[headers[key]]:'';
  const category=String(value('category')??'').trim(),name=String(value('name')??'').trim(),barcode=String(value('barcode')??'').trim();
  const cost=parseImportNumber(value('cost')),price=parseImportNumber(value('price')),quantity=parseImportNumber(value('quantity'));
  const branchId=importBranchId(value('branch'),defaultBranchId),errors=[];
  if(!category||category.length>80)errors.push('Категория пустая или длиннее 80 символов');
  if(!name||name.length>160)errors.push('Название товара пустое или длиннее 160 символов');
  if(barcode.length>80)errors.push('Штрих-код длиннее 80 символов');
  if(!Number.isFinite(cost)||cost<0||cost>1e9)errors.push('Некорректная закупочная цена');
  if(!Number.isFinite(price)||price<0||price>1e9)errors.push('Некорректная цена продажи');
  if(!Number.isInteger(quantity)||quantity<0||quantity>1e8)errors.push('Количество должно быть целым числом не меньше 0');
  if(branchId<0||branchId>4)errors.push('Некорректный филиал (укажите 1–5 или название филиала)');
  if(AUTH_USER?.role==='admin'&&branchId!==Number(AUTH_USER.branchId))errors.push('Администратор может импортировать только в свой филиал');
  const identity=barcode?'b:'+barcode.toLowerCase():'n:'+normalizeImportHeader(name)+'|'+normalizeImportHeader(category);
  const duplicateKey=identity+'|branch:'+branchId;
  if(fileDuplicates.has(duplicateKey))errors.push('В файле повторяется товар для того же филиала');
  if(barcode){const prior=barcodeNames.get(barcode.toLowerCase());if(prior&&(prior.name.toLowerCase()!==name.toLowerCase()||prior.category.toLowerCase()!==category.toLowerCase()))errors.push('Один штрих-код указан у разных товаров');else barcodeNames.set(barcode.toLowerCase(),{name,category});}
  fileDuplicates.add(duplicateKey);
  parsed.push({rowNumber:i+1,category,name,barcode,cost,price,quantity,branchId,errors});
  if(parsed.length>IMPORT_MAX_ROWS)throw new Error(`В одном файле не должно быть больше ${IMPORT_MAX_ROWS.toLocaleString('ru-RU')} строк. Разделите файл на части.`);
 }
 return parsed;
}
