 const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='moy-market-import-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
